CREATE TABLE public.wa_processing_control(id integer PRIMARY KEY DEFAULT 1 CHECK(id=1),lease_until timestamptz,lease_token uuid,paused_reason text);
GRANT ALL ON public.wa_processing_control TO service_role; ALTER TABLE public.wa_processing_control ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.wa_acquire_lease(p_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.wa_processing_control(id) VALUES(1) ON CONFLICT DO NOTHING; UPDATE public.wa_processing_control SET lease_token=p_token,lease_until=now()+interval '5 minutes' WHERE id=1 AND paused_reason IS NULL AND (lease_until IS NULL OR lease_until<now()); RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.wa_acquire_lease(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.wa_acquire_lease(uuid) TO service_role;
CREATE TABLE public.wa_delivery_statuses(delivery_id text NOT NULL,provider_id text NOT NULL,status text NOT NULL,provider_at timestamptz NOT NULL,errors jsonb,applied boolean NOT NULL DEFAULT false,PRIMARY KEY(delivery_id,provider_id,status,provider_at));
GRANT ALL ON public.wa_delivery_statuses TO service_role; ALTER TABLE public.wa_delivery_statuses ENABLE ROW LEVEL SECURITY;
CREATE INDEX wa_status_pending ON public.wa_delivery_statuses(provider_id,applied);
CREATE FUNCTION public.wa_finalize_appointment(p_message text,p_user uuid,p_appointment jsonb,p_reply text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE source_phone text; BEGIN SELECT phone INTO source_phone FROM public.wa_assistant_messages WHERE id=p_message FOR UPDATE; IF NOT EXISTS(SELECT 1 FROM public.wa_phone_links WHERE user_id=p_user AND phone=source_phone) THEN RAISE EXCEPTION 'Phone link invalid'; END IF; INSERT INTO public.appointments(id,user_id,title,date,time,description,category,reminder,done) VALUES('wa-'||p_message,p_user,p_appointment->>'title',p_appointment->>'date',p_appointment->>'time',COALESCE(p_appointment->>'description',''),COALESCE(p_appointment->>'category','outro'),15,false) ON CONFLICT(user_id,id) DO NOTHING; INSERT INTO public.wa_replies(inbound_id,phone,body) VALUES(p_message,source_phone,p_reply) ON CONFLICT(inbound_id) DO NOTHING; UPDATE public.wa_assistant_messages SET state='created',appointment_id='wa-'||p_message,user_id=p_user WHERE id=p_message; END $$;
REVOKE ALL ON FUNCTION public.wa_finalize_appointment(text,uuid,jsonb,text) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.wa_finalize_appointment(text,uuid,jsonb,text) TO service_role;